        styleDarkAccountCTA(createAccountButton, title: "Create Free Account / Sign In to Sync")
        createAccountButton.addTarget(self, action: #selector(tapAccountAuth), for: .touchUpInside)
        stack.addArrangedSubview(createAccountButton)

        let footerRow = UIStackView(arrangedSubviews: [restoreButton, manageButton])
        footerRow.axis = .horizontal
        footerRow.distribution = .fillEqually
        footerRow.spacing = 8

        restoreButton.setTitle("Restore Purchases", for: .normal)
        restoreButton.titleLabel?.font = UIFont.systemFont(ofSize: 13, weight: .bold)
        restoreButton.setTitleColor(UIColor(red: 0.059, green: 0.478, blue: 0.290, alpha: 1.0), for: .normal)
        restoreButton.addTarget(self, action: #selector(tapRestore), for: .touchUpInside)

        manageButton.setTitle("Manage Subscription", for: .normal)
        manageButton.titleLabel?.font = UIFont.systemFont(ofSize: 13, weight: .semibold)
        manageButton.setTitleColor(UIColor(red: 0.278, green: 0.333, blue: 0.412, alpha: 1.0), for: .normal)
        manageButton.addTarget(self, action: #selector(tapManage), for: .touchUpInside)

        stack.addArrangedSubview(footerRow)

        let continueFreeBtn = UIButton(type: .system)
        continueFreeBtn.setTitle("Continue with Free Plan (0–100 Scores + 3 Weekly Swaps) →", for: .normal)
        continueFreeBtn.titleLabel?.font = UIFont.systemFont(ofSize: 12.5, weight: .semibold)
        continueFreeBtn.titleLabel?.numberOfLines = 2
        continueFreeBtn.titleLabel?.textAlignment = .center
        continueFreeBtn.setTitleColor(UIColor(red: 0.392, green: 0.455, blue: 0.545, alpha: 1.0), for: .normal)
        continueFreeBtn.addTarget(self, action: #selector(tapClose), for: .touchUpInside)
        stack.addArrangedSubview(continueFreeBtn)

        NSLayoutConstraint.activate([
            scroll.topAnchor.constraint(equalTo: view.safeAreaLayoutGuide.topAnchor),
            scroll.leadingAnchor.constraint(equalTo: view.leadingAnchor),
            scroll.trailingAnchor.constraint(equalTo: view.trailingAnchor),
            scroll.bottomAnchor.constraint(equalTo: view.bottomAnchor),

            stack.topAnchor.constraint(equalTo: scroll.contentLayoutGuide.topAnchor, constant: 18),
            stack.leadingAnchor.constraint(equalTo: scroll.frameLayoutGuide.leadingAnchor, constant: 18),
            stack.trailingAnchor.constraint(equalTo: scroll.frameLayoutGuide.trailingAnchor, constant: -18),
            stack.bottomAnchor.constraint(equalTo: scroll.contentLayoutGuide.bottomAnchor, constant: -24)
        ])

        loadStoreKitProducts()
    }

    private func stylePrimaryCTA(_ btn: UIButton, title: String) {
        btn.setTitle(title, for: .normal)
        btn.titleLabel?.font = UIFont.systemFont(ofSize: 15, weight: .heavy)
        btn.titleLabel?.numberOfLines = 2
        btn.titleLabel?.textAlignment = .center
        btn.backgroundColor = UIColor(red: 0.086, green: 0.639, blue: 0.290, alpha: 1.0)
        btn.setTitleColor(.white, for: .normal)
        btn.layer.cornerRadius = 14
        btn.contentEdgeInsets = UIEdgeInsets(top: 14, left: 14, bottom: 14, right: 14)
    }

    private func styleSecondaryCTA(_ btn: UIButton, title: String) {
        btn.setTitle(title, for: .normal)
        btn.titleLabel?.font = UIFont.systemFont(ofSize: 14, weight: .bold)
        btn.backgroundColor = .white
        btn.setTitleColor(UIColor(red: 0.059, green: 0.090, blue: 0.165, alpha: 1.0), for: .normal)
        btn.layer.cornerRadius = 14
        btn.layer.borderWidth = 1.5
        btn.layer.borderColor = UIColor(red: 0.796, green: 0.835, blue: 0.882, alpha: 1.0).cgColor
        btn.contentEdgeInsets = UIEdgeInsets(top: 12, left: 14, bottom: 12, right: 14)
    }

    private func styleDarkAccountCTA(_ btn: UIButton, title: String) {
        btn.setTitle(title, for: .normal)
        btn.titleLabel?.font = UIFont.systemFont(ofSize: 14, weight: .bold)
        btn.backgroundColor = UIColor(red: 0.059, green: 0.090, blue: 0.165, alpha: 1.0)
        btn.setTitleColor(.white, for: .normal)
        btn.layer.cornerRadius = 14
        btn.contentEdgeInsets = UIEdgeInsets(top: 12, left: 14, bottom: 12, right: 14)
    }

    private func loadStoreKitProducts() {
        spinner.startAnimating()
        statusLabel.text = "Checking App Store plans…"
        annualButton.isHidden = true
        monthlyButton.isHidden = true

        Task { @MainActor [weak self] in
            guard let self = self else { return }
            do {
                let products = try await StoreKit.Product.products(for: [
                    Self.annualProductID,
                    Self.monthlyProductID
                ])
                self.spinner.stopAnimating()
                self.annualProduct = products.first(where: { $0.id == Self.annualProductID })
                self.monthlyProduct = products.first(where: { $0.id == Self.monthlyProductID })

                if let annual = self.annualProduct {
                    self.annualButton.setTitle("Start 7-Day Free Trial • Annual (\(annual.displayPrice)/yr)", for: .normal)
                    self.annualButton.isHidden = false
                }
                if let monthly = self.monthlyProduct {
                    self.monthlyButton.setTitle("Monthly Plan (\(monthly.displayPrice)/mo)", for: .normal)
                    self.monthlyButton.isHidden = false
                }

                if self.annualProduct == nil && self.monthlyProduct == nil {
                    self.statusLabel.text = "✓ Your Watchlist is saved! TestFlight In-App Purchase plans are finishing App Store review — create your free account below to sync across iPhone & Web, or scan free right now."
                } else {
                    self.statusLabel.text = "✓ Watchlist saved! Choose a plan or create a free account to sync."
                }
            } catch {
                self.spinner.stopAnimating()
                self.statusLabel.text = "✓ Watchlist saved! Create your free account below to sync across iPhone & Web, or continue scanning free."
            }
        }
    }

    private func purchase(_ product: StoreKit.Product) {
        spinner.startAnimating()
        statusLabel.text = "Confirming with Apple Face ID…"
        annualButton.isEnabled = false
        monthlyButton.isEnabled = false

        Task { @MainActor [weak self] in
            guard let self = self else { return }
            defer {
                self.spinner.stopAnimating()
                self.annualButton.isEnabled = true
                self.monthlyButton.isEnabled = true
            }
            do {
                let result = try await product.purchase()
                switch result {
                case .success(let verification):
                    switch verification {
                    case .verified(let transaction):
                        self.statusLabel.text = "🎉 Activating Family Pro…"
                        await self.onVerifiedPurchase(verification.jwsRepresentation, transaction.productID, false)
                        await transaction.finish()
                        self.dismiss(animated: true)
                    case .unverified:
                        self.statusLabel.text = "Apple could not verify this transaction. Please try Restore Purchases."
                    }
                case .userCancelled:
                    self.statusLabel.text = "No charge made — continue scanning free anytime."
                case .pending:
                    self.statusLabel.text = "Purchase is pending Ask-to-Buy approval."
                @unknown default:
                    self.statusLabel.text = ""
                }
            } catch {
                self.statusLabel.text = error.localizedDescription
            }
        }
    }

    @objc private func tapAnnual() {
        guard let prod = annualProduct else { return }
        purchase(prod)
    }

    @objc private func tapMonthly() {
        guard let prod = monthlyProduct else { return }
        purchase(prod)
    }

    @objc private func tapAccountAuth() {
        let callback = onOpenAccountAuth
        dismiss(animated: true) {
            callback("signup")
        }
    }

    @objc private func tapRestore() {
        spinner.startAnimating()
        statusLabel.text = "Restoring Apple subscriptions…"
        Task { @MainActor [weak self] in
            guard let self = self else { return }
            defer { self.spinner.stopAnimating() }
            do {
                try await AppStore.sync()
                var restoredAny = false
                for await verification in StoreKit.Transaction.currentEntitlements {
                    if case .verified(let tx) = verification,
                       (tx.productID == Self.annualProductID || tx.productID == Self.monthlyProductID) {
                        await self.onVerifiedPurchase(verification.jwsRepresentation, tx.productID, true)
                        restoredAny = true
                    }
                }
                if restoredAny {
                    self.dismiss(animated: true)
                } else {
                    self.statusLabel.text = "No active Apple subscription found on this Apple ID. Bought on heybroc.com? Tap 'Create Free Account / Sign In' to sync!"
                }
            } catch {
                self.statusLabel.text = error.localizedDescription
            }
        }
    }

    @objc private func tapManage() {
        Task { @MainActor [weak self] in
            guard let scene = self?.view.window?.windowScene else { return }
            try? await AppStore.showManageSubscriptions(in: scene)
        }
    }

    @objc private func tapClose() {
        dismiss(animated: true)
    }
}

